import { computed, ref } from 'vue'
import { pointsApi, type PointsBalance } from '@/scripts/pointsApi'
import { api } from '@/scripts/api'

/**
 * 积分系统Composable
 */
export function usePoints() {
  const balance = ref<number>(0)
  const loading = ref<boolean>(false)
  const error = ref<string | null>(null)

  const formattedBalance = computed(() => {
    return Math.round(balance.value).toString()
  })

  const isInsufficient = computed(() => {
    return balance.value < 0
  })

  async function fetchBalance() {
    try {
      const data: PointsBalance = await pointsApi.getBalance()
      balance.value = data.balance
    } catch (e) {
      error.value = e instanceof Error ? e.message : 'Failed to fetch balance'
      console.error(error.value)
    }
  }

  function setBalance(newBalance: number) {
    balance.value = newBalance
  }

  return {
    balance,
    loading,
    error,
    formattedBalance,
    isInsufficient,
    fetchBalance,
    setBalance
  }
}
